UPDATE zangraf_products AS product
SET data=jsonb_set(jsonb_set(product.data,'{albumPricing}',source.value->'albumPricing'),'{options,finishes}',source.value->'finishes'),updated_at=now()
FROM source
WHERE EXISTS(SELECT 1 FROM first_run)
 AND product.id=source.value->>'id'
 AND COALESCE(product.data->>'kind','album')='album'
 AND product.data->'options'->'sizes'=jsonb_build_array(source.value->>'size')
 AND lower(regexp_replace(product.data->'options'->'covers'->>0,'[- ]','', 'g'))=ANY(ARRAY[lower(regexp_replace(source.value->>'cover','[- ]','', 'g')),CASE WHEN source.value->>'cover'='Anti-Risco' THEN 'antirrisco' ELSE '' END])
 AND (product.data->>'priceCents') IS NULL
 AND COALESCE(jsonb_array_length(product.data->'albumPricing'),0)=0
 AND COALESCE(jsonb_array_length(product.data->'options'->'finishes'),0)=0;
COMMIT;
